   `<div class="panel" style="margin-top:14px;background:#f5f9fc"><h3>${E('تخصيص دفعة مصروف لدورة التربية','Allocate an expense lot to a cycle')}</h3>
   <p class="muted">${E('الدفعة لا تدخل في ربح الدورة بمجرد الشراء؛ يتم احتسابها مرة واحدة عند تخصيص الكمية لدورة. الكتاكيت والعلف والأدوية تُسجل من شاشاتها المعتادة.','Buying a lot does not charge a cycle; allocating a quantity charges it once. Enter chicks, feed and health items via their standard screens.')}</p>
   <div class="v410-grid">${select('v410IssueCycle','الدورة / العنبر','Cycle / house',[])}${select('v410IssueLot','دفعة المصروف','Expense lot',[])}${fields([['v410IssueQty','الكمية المخصصة','Allocated quantity','number','min="0.001" step="any" value="1"'],['v410IssueDate','تاريخ الصرف','Issue date','date']])}</div>
   <div class="actions">${btn('v410IssueExpense','صرف الدفعة على الدورة','Charge lot to cycle')}</div>
   </div>`;
  $('inventory').appendChild(inv);inv.addEventListener('click',event=>{const button=event.target.closest('[data-v410-return]');if(!button)return;const id=button.getAttribute('data-v410-return'),qty=Number(document.getElementById('v410ReturnQty_'+id)?.value);if(!window.PFM_V410.returnIssue(id,qty))out('تعذر تسجيل المرتجع؛ تحقق من الكمية وصلاحية الدورة.','Return rejected. Check quantity and cycle access.');});
  function appendLotChoice(sectionId,gridSelector,selectId,ar,en){const grid=document.querySelector('#'+sectionId+' '+gridSelector);if(!grid)return;const el=document.createElement('div');el.className='field v410-lot-choice';el.innerHTML=select(selectId,ar,en,[['','بدون مخزون — تكلفة مباشرة','Direct cost (no stock)']]);grid.appendChild(el);}
  appendLotChoice('feed','.scope-form-grid','v410FeedLot','دفعة العلف المستخدمة (اختياري)','Feed purchase lot (optional)');
  appendLotChoice('meds','.scope-form-grid','v410MedLot','دفعة الدواء المستخدمة (اختياري)','Medicine purchase lot (optional)');
  function addDirectTax(section,kind){const grid=document.querySelector('#'+section+' .scope-form-grid');const el=document.createElement('div');el.className='v410-direct-tax';el.innerHTML=select('v410'+kind+'VatMode','السعر المباشر','Direct entry price',[['excluded','غير شامل الضريبة','Excluding VAT'],['included','شامل الضريبة','Including VAT']])+fields([['v410'+kind+'VatRate','الضريبة %','VAT %','number','min="0" max="100" value="0" step="any"'],['v410'+kind+'VatReclaim','الضريبة المستردة %','Recoverable VAT %','number','min="0" max="100" value="100" step="any"']]);grid.appendChild(el);}
  addDirectTax('feed','Feed');addDirectTax('meds','Med');
  const salegrid=document.querySelector('#sales .grid');const saleVat=document.createElement('div');saleVat.className='v410-sales-vat';saleVat.innerHTML=select('v410SaleVatMode','السعر المسجل','Entered price',[['excluded','غير شامل الضريبة','Excluding VAT'],['included','شامل الضريبة','Including VAT']])+fields([['v410SaleVatRate','ضريبة المبيعات %','Sales VAT %','number','min="0" max="100" step="any" value="0"']]);salegrid.appendChild(saleVat);
  const fin=document.createElement('div');fin.id='v410-financial-dashboard';fin.className='v410-financial-dashboard';
  fin.innerHTML=`<div class="panel v410-panel">${title('نظام إدارة التكاليف والأرباح V4.10','V4.10 Cost & Profit Management')}<div id="v410DashboardCards"></div><div id="v410FinanceDistribution"></div></div>`+
   `<details class="panel v410-panel" open><summary>${E('تكلفة الكتاكيت وضريبة الشراء','Chick purchase and VAT')}</summary><div class="v410-grid">`+
   select('v410ChickMode','أساس التسعير','Pricing method',[['unit','عدد الكتاكيت المدفوعة × السعر','Billed birds × unit price'],['invoice','إجمالي الفاتورة','Invoice total']])+fields([['v410ChickBilled','عدد الكتاكيت المدفوعة','Billed chicks','number','min="0" step="1"'],['v410ChickFree','عدد الكتاكيت المجانية','Free chicks','number','min="0" step="1"'],['v410ChickUnitPrice','سعر الكتكوت المدفوع','Paid chick unit price','number','min="0" step="any"'],['v410ChickInvoice','إجمالي الفاتورة','Total invoice amount','number','min="0" step="any"'],['v410ChickDiscount','الخصم','Discount','number','min="0" step="any" value="0"'],['v410ChickFreight','النقل غير المدرج بالفاتورة','Extra freight outside invoice','number','min="0" step="any" value="0"']])+select('v410ChickVatMode','طريقة السعر','Price mode',[['excluded','غير شامل الضريبة','Excluding VAT'],['included','شامل الضريبة','Including VAT']])+fields([['v410ChickVatRate','الضريبة %','VAT %','number','min="0" max="100" step="any" value="0"'],['v410ChickReclaim','نسبة الاسترداد %','Recoverable %','number','min="0" max="100" step="any" value="100"']])+'</div><div class="actions">'+btn('v410SaveChicks','حفظ تكلفة الكتاكيت','Save chick cost')+'</div><div id="v410ChickStatus" class="muted"></div></details>'+
   `<details class="panel v410-panel"><summary>${E('سجل المصروفات التفصيلي وضريبة المشتريات','Detailed expenses & input VAT')}</summary><div class="v410-grid">`+
   select('v410ExpenseCategory','بند المصروف','Expense category',PROJECT_EXPENSE_TYPES.map(x=>[x,x,UI_EN[x]||x]))+
   fields([['v410ExpenseDate','التاريخ','Date','date'],['v410ExpenseQty','الكمية','Quantity','number','min="0.00001" step="any" value="1"'],['v410ExpensePrice','قيمة الوحدة','Unit price','number','min="0" step="any"'],['v410ExpenseSupplier','المورد','Supplier'],['v410ExpenseInvoice','رقم الفاتورة','Invoice number'],['v410ExpenseNote','ملاحظات','Notes']])+select('v410ExpenseMode','التكلفة المدخلة','Entered cost',[['excluded','غير شاملة للضريبة','Excluding VAT'],['included','شاملة للضريبة','Including VAT']])+fields([['v410ExpenseRate','الضريبة %','VAT %','number','min="0" max="100" value="0" step="any"'],['v410ExpenseReclaim','الضريبة القابلة للاسترداد %','Recoverable VAT %','number','min="0" max="100" value="100" step="any"']])+'</div><div class="actions">'+btn('v410SaveExpense','تسجيل مصروف الدورة','Add cycle expense')+'</div><div id="v410DetailedExpenses"></div></details>'+
   `<details class="panel v410-panel" open><summary>${E('تحليل الربحية والمبيعات المجمدة','Profitability & frozen sales')}</summary><div id="v410ProfitContent"></div></details>`+
   `<details class="panel v410-panel" open><summary>${E('الإغلاق المالي والتسوية وسجل التدقيق','Financial closing, reconciliation & audit')}</summary><div id="v410ClosingContent"></div><div class="v410-grid">${fields([['v410CloseReason','سبب التسوية / الإغلاق','Closing / reconciliation reason'],['v410ReopenReason','سبب إعادة الفتح (إلزامي)','Reopening reason (required)']])}</div><div class="actions">${btn('v410CloseCycle','إغلاق الدورة ماليًا','Financially close cycle')} ${btn('v410ReopenCycle','إعادة فتح الدورة للمالك','Owner: reopen cycle')}</div><div id="v410AuditContent" class="v410-table-scroll"></div></details>`;
  document.querySelector('#finance > .panel')?.after(fin);document.querySelectorAll('#v410-financial-dashboard summary').forEach(el=>{const ar=el.textContent.trim(),lookups={'تكلفة الكتاكيت وضريبة الشراء':'Chick purchase and VAT','سجل المصروفات التفصيلي وضريبة المشتريات':'Detailed expenses & input VAT','تحليل الربحية والمبيعات المجمدة':'Profitability & frozen sales','الإغلاق المالي والتسوية وسجل التدقيق':'Financial closing, reconciliation & audit'};const english=Object.values(lookups).includes(ar)?ar:lookups[ar]||ar;const arabic=Object.entries(lookups).find(([a,e])=>e===ar)?.[0]||ar;el.setAttribute('data-v410-ar',arabic);el.setAttribute('data-v410-en',english)});
  const self=$('v410CreateLot');self.onclick=createLot;
  $('v410LotKind').addEventListener('change',()=>{const key=$('v410LotKind').value,x=lotKinds.find(x=>x[0]===key);if(!x)return;$('v410LotItem').value=E(x[1],x[2]);$('v410LotUnit').value=key==='feed'?'كجم':key==='chicks'?'طائر':'وحدة';});
  $('v410IssueCycle').addEventListener('change',refreshExpenseIssueOptions);
