 window.PFM_V410={version:'4.10',vat,lotBalance,financialLive,totalFrozen,get state(){return v()},refresh:()=>{renderFinanceUI();renderReport();},returnIssue:function(movementId,qty){const m=byid(v().movements,movementId),l=m&&byid(v().lots,m.lotId);if(!m||!l||m.kind!=='issue'||!permit(m.cycleId)||!userCan(m.cycleId))return false;if(!['feed','med'].includes(m.sourceType))return false;const rec=(m.sourceType==='feed'?db.feed:db.meds).find(x=>x.id===m.sourceId);if(!rec)return false;const already=v().movements.filter(r=>r.kind==='return'&&r.parentId===m.id).reduce((s,r)=>s+n(r.qty),0);qty=n(qty);if(!(qty>0)||qty>m.qty-already+0.000001)return false;const back={id:uuid(),lotId:l.id,cycleId:m.cycleId,sourceType:m.sourceType,sourceId:rec.id,parentId:m.id,kind:'return',qty,unitCost:m.unitCost,cost:lotCostRecord(qty,m.unitCost),date:today(),createdAt:new Date().toISOString()};v().movements.push(back);if(m.sourceType==='feed'){rec.qty=Math.max(0,n(rec.qty)-qty)}else{rec.qty=Math.max(0,n(rec.qty)-qty);rec.cost=money(n(rec.cost)-back.cost)}track('lot_return',m.cycleId,null,back);save();return true;}};
